function activePreds() {
  return [...document.querySelectorAll('.chip.on')];
}
function updateFilterAvailability() {
  const game = $('game-filter').value;
  const scope = CARS.filter(c => game === 'all' || gameId(c) === game);
  const removed = [];
  for (const option of $('variant-filter').options) {
    option.disabled = !scope.some(c => matchesVariant(c, option.value));
    if (option.disabled && option.value === $('variant-filter').value) {
      removed.push(option.textContent); $('variant-filter').value = '';
    }
  }
  const variantScope = scope.filter(c => matchesVariant(c, $('variant-filter').value));
  for (const chip of document.querySelectorAll('.chip')) {
    chip.disabled = !variantScope.some(chip._pred);
    if (chip.disabled && chip.classList.contains('on')) {
      removed.push(chip.textContent); chip.classList.remove('on'); chip.setAttribute('aria-pressed', 'false');
    }
  }
  $('filter-status').textContent = removed.length ? `Cleared unavailable filters: ${removed.join(', ')}.` : '';
}
